// Extract document content from webhook payload
const items = $input.all();
const item = items[0].json;

// Try to get file data from binary or body
let documentContent = '';
let imageBase64 = null;

if (item.body && item.body.document_base64) {
  imageBase64 = item.body.document_base64;
  documentContent = 'Image document provided as base64';
} else if (item.body && item.body.document_text) {
  documentContent = item.body.document_text;
} else if (item.body && item.body.text) {
  documentContent = item.body.text;
} else {
  documentContent = JSON.stringify(item.body || item);
}

return [{
  json: {
    documentContent,
    imageBase64,
    hasImage: !!imageBase64
  }
}];

const response = $input.first().json;

const fail = (remarks) => {
  const r = { fullName: 'PARSE_ERROR', isValid: false, tamperingDetected: false, confidenceScore: 0, remarks };
  return [{ json: { auditResult: JSON.stringify(r), parsed: r } }];
};

// The vision call can fail or return an API-level error object.
if (response.error) {
  return fail('OpenRouter returned an error: ' + JSON.stringify(response.error).substring(0, 300));
}
if (!response.choices || !response.choices[0] || !response.choices[0].message) {
  return fail('Unexpected OpenRouter response shape: ' + JSON.stringify(response).substring(0, 300));
}

const content = response.choices[0].message.content || '';

let auditResult;
try {
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  auditResult = JSON.parse(cleaned);
} catch (e) {
  return fail('Failed to parse AI response as JSON: ' + content.substring(0, 200));
}

// Normalise the fields the IF node depends on so a missing key can never
// silently approve a document.
auditResult.isValid = auditResult.isValid === true;
auditResult.tamperingDetected = auditResult.tamperingDetected === true;
auditResult.confidenceScore = Number(auditResult.confidenceScore) || 0;

return [{ json: { auditResult: JSON.stringify(auditResult), parsed: auditResult } }];
